import React, { useEffect, useState } from 'react';
import { useForm } from 'react-hook-form';
import RiskMatrixSelector from './RiskMatrixSelector';
import RiskMatrixReference from './RiskMatrixReference';
import AssessmentForm from './AssessmentForm';
import useProjectStore from '../stores/projectStore';
import { useRiskMatrixStore } from '../stores/riskMatrixStore';
import { updateAssessments, getAssessmentsByConsequenceId } from '../services/riskAssessmentService';

// Error Alert Component remains unchanged
const ErrorAlert = ({ message }) => {
  if (!message) return null;

  return (
    <div className="p-4 mb-4 bg-red-50 border border-red-200 rounded-lg">
      <div className="flex items-center">
        <div className="flex-shrink-0">
          <svg className="h-5 w-5 text-red-400" viewBox="0 0 20 20" fill="currentColor">
            <path
              fillRule="evenodd"
              d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293-1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z"
              clipRule="evenodd"
            />
          </svg>
        </div>
        <div className="ml-3">
          <p className="text-sm text-red-700">{message}</p>
        </div>
      </div>
    </div>
  );
};

export default function RiskAssessment() {
  const {
    currentProject,
    hazardIdentificationData,
    riskAssessmentData,
    setStepData,
    setCurrentStep,
    error: storeError,
  } = useProjectStore();
  const { matrixType, setMatrixType } = useRiskMatrixStore();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [localError, setLocalError] = useState(null);
  const events = hazardIdentificationData?.events || [];

  // Log the initial events data for debugging
  console.log('Initial events data:', events.map(event => ({
    id: event.id,
    name: event.name,
    hazards_count: event.hazards?.length || 0
  })));

  const defaultValues = {
    assessments: events.flatMap(event =>
      (event.hazards || []).flatMap(hazard =>
        (hazard.consequences || []).map(consequence => {
          // Log each consequence being processed
          console.log('Processing consequence:', {
            consequence_id: consequence.id,
            event_name: event.name,
            hazard_description: hazard.description
          });

          return {
            assessment_id: null, // Will be set when loading existing assessment
            consequence_id: consequence.id,
            event: event.name,
            event_id: event.id,
            hazard: hazard.description,
            hazard_id: hazard.id,
            consequence: consequence.description,
            current_controls: consequence.current_controls || '',
            probability: '',
            severity: '',
            likelihood: '',
            impact: '',
            tolerability: '',
          };
        })
      )
    ),
  };

  // Log the final form default values
  console.log('Form default values:', {
    assessment_count: defaultValues.assessments.length,
    sample: defaultValues.assessments[0]
  });

  const { register, handleSubmit, watch, setValue } = useForm({ defaultValues });

  const watchAssessments = watch('assessments');

  // Save data changes to store
  useEffect(() => {
    const saveData = async () => {
      try {
        if (!watchAssessments?.length) return;

        // Filter assessments based on matrix type and required fields
        const validAssessments = watchAssessments.filter(assessment => {
          // Must have consequence_id
          if (!assessment.consequence_id) return false;

          // Check matrix-specific required fields
          if (matrixType === 'ICAO') {
            return assessment.probability && assessment.severity;
          }
          return assessment.likelihood && assessment.impact;
        });

        if (validAssessments.length > 0) {
          // Format data to match service structure
          const formattedData = {
            assessments: validAssessments.map(assessment => {
              const baseData = {
                consequence_id: assessment.consequence_id,
                probability: assessment.probability ? parseInt(assessment.probability, 10) : null,
                severity: assessment.severity || null,
                likelihood: assessment.likelihood ? parseInt(assessment.likelihood, 10) : null,
                impact: assessment.impact ? parseInt(assessment.impact, 10) : null,
                tolerability: assessment.tolerability || null
              };

              // Include assessment_id if it exists
              if (assessment.assessment_id) {
                baseData.id = assessment.assessment_id;
              }

              return baseData;
            })
          };

          console.log('Auto-saving assessments:', {
            count: formattedData.assessments.length,
            matrix_type: matrixType,
            sample: formattedData.assessments[0]
          });

          await setStepData(3, formattedData);
        }
      } catch (error) {
        console.error('Error auto-saving:', error);
      }
    };

    const timeoutId = setTimeout(saveData, 1000);
    return () => clearTimeout(timeoutId);
  }, [watchAssessments, setStepData, matrixType]);

  // Load existing assessments from database
  useEffect(() => {
    const loadExistingAssessments = async () => {
      if (!currentProject?.id) return;

      try {
        setLocalError(null);
        const formAssessments = watchAssessments;

        // Validate all assessments have consequence IDs
        const missingIds = formAssessments.filter(assessment => !assessment.consequence_id);
        if (missingIds.length > 0) {
          const errorDetails = missingIds.map(assessment =>
            `Event: ${assessment.event}, Hazard: ${assessment.hazard}`
          ).join('\n');

          setLocalError(
            `Some consequences are missing IDs. This may indicate a data synchronization issue. ` +
            `Please try refreshing the page or contact support if the issue persists.\n\nAffected items:\n${errorDetails}`
          );
          return;
        }

        // Proceed with loading existing assessments
        for (const assessment of formAssessments) {

          const existingAssessment = await getAssessmentsByConsequenceId(assessment.consequence_id);
          if (existingAssessment) {
            // Find the matching assessment using the consequence ID
            const index = formAssessments.findIndex(a =>
              a.consequence_id === existingAssessment.consequence_id
            );

            if (index !== -1) {
              // Update form values with existing assessment data
              setValue(`assessments.${index}.assessment_id`, existingAssessment.id);
              setValue(`assessments.${index}.probability`, existingAssessment.probability || '');
              setValue(`assessments.${index}.severity`, existingAssessment.severity || '');
              setValue(`assessments.${index}.likelihood`, existingAssessment.likelihood || '');
              setValue(`assessments.${index}.impact`, existingAssessment.impact || '');
              setValue(`assessments.${index}.tolerability`, existingAssessment.tolerability || '');

              // Update matrix type if not already set
              if (!matrixType && existingAssessment.matrix_type) {
                setMatrixType(existingAssessment.matrix_type);
              }

              // Update consequence data from nested structure
              setValue(`assessments.${index}.event`, existingAssessment.consequence.hazard.event.name);
              setValue(`assessments.${index}.event_id`, existingAssessment.consequence.hazard.event.id);
              setValue(`assessments.${index}.hazard`, existingAssessment.consequence.hazard.description);
              setValue(`assessments.${index}.hazard_id`, existingAssessment.consequence.hazard.id);
              setValue(`assessments.${index}.consequence`, existingAssessment.consequence.description);
              setValue(`assessments.${index}.current_controls`, existingAssessment.consequence.current_controls || '');
            }
          }
        }
      } catch (error) {
        console.error('Error loading existing assessments:', error);
        setLocalError('Failed to load existing assessments. Please try again.');
      }
    };

    loadExistingAssessments();
  }, [currentProject?.id, setValue, setMatrixType, watchAssessments]);

  const handleFormSubmit = async data => {
    try {
      setIsSubmitting(true);
      setLocalError(null);

      const { assessments } = data;
      const invalidAssessments = assessments.filter(assessment => !assessment.consequence_id);

      if (invalidAssessments.length > 0) {
        console.error('Invalid assessments detected:', invalidAssessments);
        setLocalError('One or more assessments are missing required fields.');
        return;
      }

      // Format the data to match the service's expected structure
      const formattedData = {
        assessments: assessments.map(assessment => {
          const baseData = {
            consequence_id: assessment.consequence_id,
            probability: assessment.probability ? parseInt(assessment.probability, 10) : null,
            severity: assessment.severity || null,
            likelihood: assessment.likelihood ? parseInt(assessment.likelihood, 10) : null,
            impact: assessment.impact ? parseInt(assessment.impact, 10) : null,
            tolerability: assessment.tolerability || null
          };

          // If we have an existing assessment ID, include it
          if (assessment.assessment_id) {
            baseData.id = assessment.assessment_id;
          }

          return baseData;
        }),
      };

      console.log('Submitting assessment data:', {
        assessments: formattedData.assessments.map(a => ({
          id: a.id,
          consequence_id: a.consequence_id,
          probability: a.probability,
          severity: a.severity
        }))
      });

      const result = await updateAssessments(formattedData, matrixType);

      if (!result) {
        throw new Error('Failed to save assessments.');
      }

      const saved = await setStepData(3, result);
      if (!saved) throw new Error('Failed to save risk assessment data to store.');

      setCurrentStep(4);
    } catch (error) {
      console.error('Error submitting form:', error);
      setLocalError(error.message || 'Failed to save risk assessments. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto p-6 space-y-6">
      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-bold text-gray-800 mb-6">Risk Assessment</h2>
        <RiskMatrixSelector />
        <RiskMatrixReference />
      </div>

      {(storeError || localError) && <ErrorAlert message={localError || storeError} />}

      {Object.keys(watchAssessments || {}).length > 0 ? (
        <AssessmentForm
          groupedAssessments={watchAssessments.reduce((acc, assessment) => {
            if (!acc[assessment.event_id]) {
              acc[assessment.event_id] = { event: assessment.event, assessments: [] };
            }
            acc[assessment.event_id].assessments.push(assessment);
            return acc;
          }, {})}
          setValue={setValue}
          onSubmit={handleSubmit(handleFormSubmit)}
          isSubmitting={isSubmitting}
        />
      ) : (
        <div className="bg-white rounded-lg shadow-md p-6">
          <p className="text-gray-600 text-center">
            No hazards or consequences found. Please add hazards in the previous step.
          </p>
        </div>
      )}
    </div>
  );
}
